import { test } from "@e2e/fixtures";
import * as ui from "@e2e/ui-actions";

test.describe("Canvas highlighting", () => {
  test.use({
    inspectorOptions: {
      inspectMode: true,
    },
  });

  test("Balance check updates canvas highlighting and active node", async ({ inspectorPage }) => {
    await test.step("Send balance check and assert canvas highlighting and active node", async () => {
      await ui.inspectorShell.actions(inspectorPage).sendMessage("What's my balance?");
      await ui.conversationLog
        .assertions(inspectorPage)
        .conversationEventReached("utter_current_balance");
      await ui.inspectorCanvas.assertions(inspectorPage).highlightedEdgeCountAtLeast(1);
      await ui.inspectorCanvas.assertions(inspectorPage).selectedNodeCountAtLeast(1);
    });
  });
});
